package com.medcore.backend.api.auditoria;import org.springframework.data.domain.*;import org.springframework.data.web.PageableDefault;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/admin/auditoria")@PreAuthorize("hasRole('ADMIN')")public class AuditoriaController{private final AuditoriaService service;public AuditoriaController(AuditoriaService service){this.service=service;}@GetMapping public Page<AuditoriaResponse>listar(@PageableDefault(size=20,sort="fechaHora")Pageable p){return service.listar(p);}}
